BEGIN TRANSACTION;
CREATE TABLE areas (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT DEFAULT '', titulo TEXT DEFAULT '', descripcion TEXT DEFAULT '');
CREATE TABLE clientes (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT DEFAULT '', dni TEXT DEFAULT '', telefono TEXT DEFAULT '', ocupacion TEXT DEFAULT '', direccion TEXT DEFAULT '', zona TEXT DEFAULT '', fecha_registro TEXT DEFAULT '', tipo_servicio TEXT DEFAULT '', sueldo_ofrecido TEXT DEFAULT '', horario TEXT DEFAULT '', dias_libres TEXT DEFAULT '', personas_hogar TEXT DEFAULT '', ninos TEXT DEFAULT '', mascotas TEXT DEFAULT '', tareas TEXT DEFAULT '', requisitos TEXT DEFAULT '', fecha_necesita TEXT DEFAULT '', notas TEXT DEFAULT '', estado TEXT DEFAULT '', meses_garantia TEXT DEFAULT '');
CREATE TABLE colocaciones (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id TEXT DEFAULT '', trabajadora_id TEXT DEFAULT '', fecha_enlace TEXT DEFAULT '', estado TEXT DEFAULT '', notas TEXT DEFAULT '', sueldo_acordado TEXT DEFAULT '', porcentaje TEXT DEFAULT '', comision TEXT DEFAULT '', comision_pagada TEXT DEFAULT '', fecha_pago TEXT DEFAULT '', contrato_firmado TEXT DEFAULT '', fecha_firma TEXT DEFAULT '', firma_cliente TEXT DEFAULT '', firma_trabajadora TEXT DEFAULT '', firma_agencia TEXT DEFAULT '', garantia TEXT DEFAULT '', meses_garantia TEXT DEFAULT '', fecha_inicio TEXT DEFAULT '', fin_garantia TEXT DEFAULT '', reemplazo_de TEXT DEFAULT '', fecha_contrato TEXT DEFAULT '', puesto TEXT DEFAULT '', modalidad TEXT DEFAULT '', descanso TEXT DEFAULT '');
CREATE TABLE trabajadoras (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT DEFAULT '', dni TEXT DEFAULT '', telefono TEXT DEFAULT '', edad TEXT DEFAULT '', direccion TEXT DEFAULT '', zona TEXT DEFAULT '', tipo_servicio TEXT DEFAULT '', cama_adentro TEXT DEFAULT '', experiencia TEXT DEFAULT '', referencias TEXT DEFAULT '', doc_dni TEXT DEFAULT '', doc_antecedentes TEXT DEFAULT '', doc_salud TEXT DEFAULT '', doc_domicilio TEXT DEFAULT '', doc_referencias TEXT DEFAULT '', estado TEXT DEFAULT '', notas TEXT DEFAULT '');
DELETE FROM "sqlite_sequence";
COMMIT;
